#!/usr/bin/env python3
"""Generate the Unicode lookup tables used by the Rust sources (src/tables.rs).

Tables:
  * ZERO_WIDTH: ranges of characters that occupy no terminal column
  * WIDE:       ranges of East Asian wide / fullwidth characters
  * DIGIT:      ranges of Unicode decimal digits (general category Nd)
"""
import unicodedata
import sys


def ranges(pred):
    out = []
    start = None
    for cp in range(0x110000):
        ok = pred(cp)
        if ok and start is None:
            start = cp
        elif not ok and start is not None:
            out.append((start, cp - 1))
            start = None
    if start is not None:
        out.append((start, 0x10FFFF))
    return out


def zero_width(cp):
    if cp == 0x00AD:
        return False
    c = chr(cp)
    cat = unicodedata.category(c)
    if cat in ('Mn', 'Me', 'Cf'):
        return True
    if 0x1160 <= cp <= 0x11FF:
        return True
    if cp == 0x200B:
        return True
    return False


WIDE_BLOCKS = [(0x3400, 0x4DBF), (0x4E00, 0x9FFF), (0xF900, 0xFAFF),
               (0x20000, 0x2FFFD), (0x30000, 0x3FFFD)]


def wide(cp):
    if zero_width(cp):
        return False
    for a, b in WIDE_BLOCKS:
        if a <= cp <= b:
            return True
    return unicodedata.east_asian_width(chr(cp)) in ('W', 'F')


def digit(cp):
    return unicodedata.category(chr(cp)) == 'Nd'


def emit(name, rs):
    lines = ["pub static %s: &[(u32, u32)] = &[" % name]
    row = []
    for a, b in rs:
        row.append("(0x%X, 0x%X)," % (a, b))
        if len(row) == 4:
            lines.append("    " + " ".join(row))
            row = []
    if row:
        lines.append("    " + " ".join(row))
    lines.append("];")
    return "\n".join(lines)


def main():
    parts = ["// Generated by tools/gen_tables.py -- do not edit by hand.", ""]
    parts.append(emit("ZERO_WIDTH", ranges(zero_width)))
    parts.append("")
    parts.append(emit("WIDE", ranges(wide)))
    parts.append("")
    parts.append(emit("DIGIT", ranges(digit)))
    parts.append("")
    sys.stdout.write("\n".join(parts))


if __name__ == '__main__':
    main()
EOF
