//! A small command line option parser.
//!
//! It follows the conventions of the classic `getopts` style parser:
//! short options can be clustered (`-bA`), options taking a value can
//! get it glued (`-d2`, `--depth=2`) or as the following argument, and
//! free arguments may be interleaved with options.  A lone `--` ends
//! option processing.

use std::fmt;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum HasArg {
    No,
    Maybe,
    Yes,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Occur {
    Optional,
    Multi,
}

#[derive(Clone, Debug)]
pub struct OptSpec {
    pub short: char,
    pub long: &'static str,
    pub hasarg: HasArg,
    pub occur: Occur,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Value {
    Given,
    Val(String),
}

#[derive(Debug)]
pub enum ParseError {
    ArgumentMissing(String),
    UnrecognizedOption(String),
    OptionDuplicated(String),
    UnexpectedArgument(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::ArgumentMissing(n) => write!(f, "Argument to option '{}' missing", n),
            ParseError::UnrecognizedOption(n) => write!(f, "Unrecognized option: '{}'", n),
            ParseError::OptionDuplicated(n) => write!(f, "Option '{}' given more than once", n),
            ParseError::UnexpectedArgument(n) => {
                write!(f, "Option '{}' does not take an argument", n)
            }
        }
    }
}

pub struct Matches {
    specs: Vec<OptSpec>,
    vals: Vec<Vec<Value>>,
    pub free: Vec<String>,
}

enum Name {
    Short(char),
    Long(String),
}

impl Name {
    fn label(&self) -> String {
        match self {
            Name::Short(c) => c.to_string(),
            Name::Long(s) => s.clone(),
        }
    }
}

fn looks_like_option(s: &str) -> bool {
    s.len() > 1 && s.as_bytes()[0] == b'-'
}

fn find(specs: &[OptSpec], name: &Name) -> Option<usize> {
    specs.iter().position(|o| match name {
        Name::Short(c) => o.short == *c,
        Name::Long(l) => o.long == l.as_str(),
    })
}

pub fn parse(specs: &[OptSpec], args: &[String]) -> Result<Matches, ParseError> {
    let mut vals: Vec<Vec<Value>> = vec![Vec::new(); specs.len()];
    let mut free = Vec::new();
    let mut idx = 0;

    while idx < args.len() {
        let cur = args[idx].clone();
        idx += 1;

        if !looks_like_option(&cur) {
            free.push(cur);
            continue;
        }
        if cur == "--" {
            free.extend(args[idx..].iter().cloned());
            break;
        }

        let mut names: Vec<Name> = Vec::new();
        let mut inline_arg: Option<String> = None;
        let was_long;

        if cur.as_bytes()[1] == b'-' {
            was_long = true;
            let tail = &cur[2..];
            match tail.find('=') {
                Some(p) => {
                    names.push(Name::Long(tail[..p].to_string()));
                    inline_arg = Some(tail[p + 1..].to_string());
                }
                None => names.push(Name::Long(tail.to_string())),
            }
        } else {
            was_long = false;
            for (pos, ch) in cur.char_indices().skip(1) {
                let name = Name::Short(ch);
                let id = match find(specs, &name) {
                    Some(id) => id,
                    None => return Err(ParseError::UnrecognizedOption(ch.to_string())),
                };
                names.push(name);
                let takes = specs[id].hasarg != HasArg::No;
                let next = pos + ch.len_utf8();
                if takes && next < cur.len() {
                    inline_arg = Some(cur[next..].to_string());
                    break;
                }
            }
        }

        let count = names.len();
        for (n, name) in names.iter().enumerate() {
            let name_pos = n + 1;
            let id = match find(specs, name) {
                Some(id) => id,
                None => return Err(ParseError::UnrecognizedOption(name.label())),
            };
            match specs[id].hasarg {
                HasArg::No => {
                    if name_pos == count && inline_arg.is_some() {
                        return Err(ParseError::UnexpectedArgument(name.label()));
                    }
                    vals[id].push(Value::Given);
                }
                HasArg::Maybe => {
                    if let Some(v) = inline_arg.take() {
                        vals[id].push(Value::Val(v));
                    } else if was_long
                        || name_pos < count
                        || idx >= args.len()
                        || looks_like_option(&args[idx])
                    {
                        vals[id].push(Value::Given);
                    } else {
                        vals[id].push(Value::Val(args[idx].clone()));
                        idx += 1;
                    }
                }
                HasArg::Yes => {
                    if let Some(v) = inline_arg.take() {
                        vals[id].push(Value::Val(v));
                    } else if idx < args.len() {
                        vals[id].push(Value::Val(args[idx].clone()));
                        idx += 1;
                    } else {
                        return Err(ParseError::ArgumentMissing(name.label()));
                    }
                }
            }
        }
    }

    for (i, spec) in specs.iter().enumerate() {
        if spec.occur != Occur::Multi && vals[i].len() > 1 {
            return Err(ParseError::OptionDuplicated(spec.long.to_string()));
        }
    }

    Ok(Matches {
        specs: specs.to_vec(),
        vals,
        free,
    })
}

impl Matches {
    fn index(&self, name: &str) -> Option<usize> {
        self.specs
            .iter()
            .position(|o| o.long == name || (name.chars().count() == 1 && name.starts_with(o.short)))
    }

    pub fn present(&self, name: &str) -> bool {
        match self.index(name) {
            Some(i) => !self.vals[i].is_empty(),
            None => false,
        }
    }

    /// Value of an option with an optional argument: `None` when absent,
    /// the given value, or `default` when the option was given bare.
    pub fn value_or(&self, name: &str, default: &str) -> Option<String> {
        let i = self.index(name)?;
        match self.vals[i].first() {
            None => None,
            Some(Value::Given) => Some(default.to_string()),
            Some(Value::Val(s)) => Some(s.clone()),
        }
    }

    pub fn all_values(&self, name: &str) -> Vec<String> {
        match self.index(name) {
            Some(i) => self.vals[i]
                .iter()
                .filter_map(|v| match v {
                    Value::Val(s) => Some(s.clone()),
                    Value::Given => None,
                })
                .collect(),
            None => Vec::new(),
        }
    }
}
EOF
