//! Terminal column width of text and a few character class helpers.

use crate::tables::{DIGIT, WIDE, ZERO_WIDTH};

fn in_table(table: &[(u32, u32)], c: char) -> bool {
    let cp = c as u32;
    table
        .binary_search_by(|&(lo, hi)| {
            if hi < cp {
                std::cmp::Ordering::Less
            } else if lo > cp {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// Number of terminal columns used by a character.  Control characters
/// count as zero columns.
pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp < 0x20 || (0x7F..0xA0).contains(&cp) {
        return 0;
    }
    if cp < 0x7F {
        return 1;
    }
    if in_table(ZERO_WIDTH, c) {
        0
    } else if in_table(WIDE, c) {
        2
    } else {
        1
    }
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

/// Unicode decimal digit (general category Nd).
pub fn is_decimal_digit(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_digit();
    }
    in_table(DIGIT, c)
}

/// Fit `name` into `max` columns.  Returns the text to print and the
/// number of padding spaces that must follow it.  Names that are too
/// long are cut on a character boundary and are not padded.
pub fn fit(name: &str, max: usize) -> (String, usize) {
    let w = str_width(name);
    if w <= max {
        return (name.to_string(), max - w);
    }
    let mut out = String::new();
    let mut used = 0;
    for c in name.chars() {
        let cw = char_width(c);
        if used + cw > max {
            break;
        }
        used += cw;
        out.push(c);
    }
    (out, 0)
}
