//! Extended grapheme cluster segmentation (a compact take on UAX #29).

use crate::tables::GRAPHEME_BREAK;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Gcb {
    Other,
    Cr,
    Lf,
    Control,
    Extend,
    Zwj,
    RegionalIndicator,
    Prepend,
    SpacingMark,
    L,
    V,
    T,
    Lv,
    Lvt,
    Pictographic,
}

fn property(c: char) -> Gcb {
    let cp = c as u32;
    let found = GRAPHEME_BREAK.binary_search_by(|&(lo, hi, _)| {
        if hi < cp {
            std::cmp::Ordering::Less
        } else if lo > cp {
            std::cmp::Ordering::Greater
        } else {
            std::cmp::Ordering::Equal
        }
    });
    let v = match found {
        Ok(i) => GRAPHEME_BREAK[i].2,
        Err(_) => 0,
    };
    match v {
        1 => Gcb::Cr,
        2 => Gcb::Lf,
        3 => Gcb::Control,
        4 => Gcb::Extend,
        5 => Gcb::Zwj,
        6 => Gcb::RegionalIndicator,
        7 => Gcb::Prepend,
        8 => Gcb::SpacingMark,
        9 => Gcb::L,
        10 => Gcb::V,
        11 => Gcb::T,
        12 => Gcb::Lv,
        13 => Gcb::Lvt,
        14 => Gcb::Pictographic,
        _ => Gcb::Other,
    }
}

/// Split a string into extended grapheme clusters.
pub fn clusters(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut prev: Option<Gcb> = None;
    // emoji sequence state: Pictographic Extend* seen (for the ZWJ rule)
    let mut pict_seq = false;
    let mut pict_zwj = false;
    let mut ri_count = 0usize;

    for (i, c) in s.char_indices() {
        let cur = property(c);
        let brk = match prev {
            None => false,
            Some(p) => !joins(p, cur, pict_zwj, ri_count),
        };
        if brk {
            out.push(&s[start..i]);
            start = i;
        }

        // update emoji state
        pict_zwj = false;
        match cur {
            Gcb::Pictographic => pict_seq = true,
            Gcb::Extend if pict_seq => {}
            Gcb::Zwj if pict_seq => {
                pict_zwj = true;
                pict_seq = false;
            }
            _ => pict_seq = false,
        }
        if cur == Gcb::RegionalIndicator {
            if brk || prev != Some(Gcb::RegionalIndicator) {
                ri_count = 1;
            } else {
                ri_count += 1;
            }
        } else {
            ri_count = 0;
        }
        prev = Some(cur);
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}

fn joins(prev: Gcb, cur: Gcb, pict_zwj: bool, ri_count: usize) -> bool {
    use Gcb::*;
    match (prev, cur) {
        (Cr, Lf) => true,
        (Cr, _) | (Lf, _) | (Control, _) => false,
        (_, Cr) | (_, Lf) | (_, Control) => false,
        (L, L) | (L, V) | (L, Lv) | (L, Lvt) => true,
        (Lv, V) | (Lv, T) | (V, V) | (V, T) => true,
        (Lvt, T) | (T, T) => true,
        (_, Extend) | (_, Zwj) => true,
        (_, SpacingMark) => true,
        (Prepend, _) => true,
        (Zwj, Pictographic) if pict_zwj => true,
        (RegionalIndicator, RegionalIndicator) => ri_count % 2 == 1,
        _ => false,
    }
}
EOF
echo ok"}

