//! LS_COLORS handling.

use std::collections::HashMap;
use std::fs::{self, Metadata};
use std::os::unix::fs::PermissionsExt;
use std::path::Path;

pub type ColorDict = HashMap<String, String>;

/// Parse the value of LS_COLORS (`key=value` pairs separated by colons).
/// Parsing stops at the first empty entry.
pub fn parse(spec: &str) -> ColorDict {
    let mut dict = ColorDict::new();
    for entry in spec.split(':') {
        if entry.is_empty() {
            break;
        }
        let (key, value) = crate::split_color_entry(entry);
        dict.insert(key.to_string(), value.to_string());
    }
    dict
}

/// Pick the colour of a file system entry.  `md` holds the metadata of
/// the entry itself (symbolic links are not followed).
pub fn lookup(dict: &ColorDict, path: &Path, md: Option<&Metadata>) -> Option<String> {
    let is_link = md.map(|m| m.file_type().is_symlink()).unwrap_or(false);
    let mode = md.map(|m| m.permissions().mode()).unwrap_or(0);

    if is_link {
        let target_ok = match fs::read_link(path) {
            Ok(target) => target.exists(),
            Err(_) => false,
        };
        if target_ok {
            if let Some(c) = dict.get("ln") {
                return Some(c.clone());
            }
        }
        if let Some(c) = dict.get("or") {
            return Some(c.clone());
        }
    }

    if path.is_dir() {
        if mode & 0o002 != 0 {
            if let Some(c) = dict.get("ow") {
                return Some(c.clone());
            }
        }
        if let Some(c) = dict.get("di") {
            return Some(c.clone());
        }
    }

    if mode & 0o111 != 0 {
        if let Some(c) = dict.get("ex") {
            return Some(c.clone());
        }
    }

    if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
        for (key, value) in dict.iter() {
            if crate::extension_key_matches(key, ext) {
                return Some(value.clone());
            }
        }
    }

    if path.is_file() {
        dict.get("fi").cloned()
    } else {
        dict.get("bd").cloned()
    }
}
EOF
