//! Building the tree of entries with their sizes.

use std::fs::{self, Metadata};
use std::os::unix::fs::MetadataExt;
use std::path::Path;

use crate::colors::{self, ColorDict};

pub const AGGREGATED: &str = "<aggregated>";

pub struct Entry {
    pub name: String,
    pub bytes: u64,
    pub color: Option<String>,
    pub children: Option<Vec<Entry>>,
}

pub struct ScanOptions {
    /// Directories deeper than this are only measured, not listed.
    pub max_depth: Option<usize>,
    /// Entries smaller than this are merged into one aggregated entry.
    pub aggregate: Option<u64>,
    pub usage: bool,
    pub files_only: bool,
    pub excludes: Vec<String>,
    pub no_hidden: bool,
    pub colors: Option<ColorDict>,
}

fn own_size(md: &Metadata, usage: bool) -> u64 {
    if usage {
        md.blocks().wrapping_mul(512)
    } else {
        md.len()
    }
}

pub fn display_name(name: &std::ffi::OsStr) -> String {
    match name.to_str() {
        Some(s) => s.to_string(),
        None => "[invalid name]".to_string(),
    }
}

fn report(name: &str, err: &std::io::Error) {
    eprintln!("Couldn't read {} ({:?})", name, err.kind());
}

/// Total size of everything below the directory `path`.
fn dir_contents_size(path: &Path, name: &str, usage: bool) -> u64 {
    let reader = match fs::read_dir(path) {
        Ok(r) => r,
        Err(e) => {
            report(name, &e);
            return 0;
        }
    };
    let mut total: u64 = 0;
    for item in reader {
        let item = match item {
            Ok(i) => i,
            Err(_) => continue,
        };
        let child_name = display_name(&item.file_name());
        match item.metadata() {
            Ok(md) => {
                total = total.wrapping_add(own_size(&md, usage));
                if md.is_dir() {
                    let sub = dir_contents_size(&item.path(), &child_name, usage);
                    total = total.wrapping_add(sub);
                }
            }
            Err(e) => report(&child_name, &e),
        }
    }
    total
}

impl Entry {
    pub fn aggregated(bytes: u64) -> Entry {
        Entry {
            name: AGGREGATED.to_string(),
            bytes,
            color: None,
            children: None,
        }
    }

    pub fn scan(path: &Path, name: String, depth: usize, opts: &ScanOptions) -> Entry {
        let md = match fs::symlink_metadata(path) {
            Ok(m) => Some(m),
            Err(e) => {
                report(&name, &e);
                None
            }
        };
        let color = match &opts.colors {
            Some(dict) => colors::lookup(dict, path, md.as_ref()),
            None => None,
        };

        let mut bytes = md.as_ref().map(|m| own_size(m, opts.usage)).unwrap_or(0);
        let mut children = None;
        let is_dir = md.as_ref().map(|m| m.is_dir()).unwrap_or(false);

        if is_dir {
            let descend = match opts.max_depth {
                Some(max) => depth < max,
                None => true,
            };
            if descend {
                match fs::read_dir(path) {
                    Ok(reader) => {
                        let list = Entry::scan_children(reader, depth, opts);
                        for c in &list {
                            bytes = bytes.wrapping_add(c.bytes);
                        }
                        children = Some(list);
                    }
                    Err(e) => {
                        report(&name, &e);
                        bytes = bytes.wrapping_add(dir_contents_size(path, &name, opts.usage));
                    }
                }
            } else {
                bytes = bytes.wrapping_add(dir_contents_size(path, &name, opts.usage));
            }
        }

        Entry {
            name,
            bytes,
            color,
            children,
        }
    }

    fn scan_children(reader: fs::ReadDir, depth: usize, opts: &ScanOptions) -> Vec<Entry> {
        let mut kept: Vec<Entry> = Vec::new();
        let mut small: u64 = 0;
        for item in reader {
            let item = match item {
                Ok(i) => i,
                Err(_) => continue,
            };
            let name = display_name(&item.file_name());
            if opts.excludes.iter().any(|x| *x == name) {
                continue;
            }
            if opts.no_hidden && name.starts_with('.') {
                continue;
            }
            let child_path = item.path();
            if opts.files_only && child_path.is_dir() {
                continue;
            }
            let child = Entry::scan(&child_path, name, depth + 1, opts);
            match opts.aggregate {
                Some(limit) if child.bytes < limit => small = small.wrapping_add(child.bytes),
                _ => kept.push(child),
            }
        }
        kept.sort_unstable_by(|a, b| b.bytes.cmp(&a.bytes));
        if small > 0 {
            kept.push(Entry::aggregated(small));
        }
        kept
    }
}
EOF
echo ok"}

