                        let list = Entry::scan_children(reader, depth, opts);
                        for c in &list {
                            bytes = bytes.wrapping_add(c.bytes);
                        }
                        children = Some(list);
                    }
                    Err(e) => {
                        report(&name, &e);
                        bytes = bytes.wrapping_add(dir_contents_size(path, &name, opts.usage));
                    }
                }
            } else {
                bytes = bytes.wrapping_add(dir_contents_size(path, &name, opts.usage));
            }
        }

        Entry {
            name,
            bytes,
            color,
            children,
        }
    }

    fn scan_children(reader: fs::ReadDir, depth: usize, opts: &ScanOptions) -> Vec<Entry> {
        let mut kept: Vec<Entry> = Vec::new();
        let mut small: u64 = 0;
        for item in reader {
            let item = match item {
                Ok(i) => i,
                Err(_) => continue,
            };
            let name = display_name(&item.file_name());
            if opts.excludes.iter().any(|x| *x == name) {
                continue;
            }
            if opts.no_hidden && name.starts_with('.') {
                continue;
            }
            let child_path = item.path();
            if opts.files_only && child_path.is_dir() {
                continue;
            }
            let child = Entry::scan(&child_path, name, depth + 1, opts);
            match opts.aggregate {
                Some(limit) if child.bytes < limit => small = small.wrapping_add(child.bytes),
                _ => kept.push(child),
            }
        }
        kept.sort_unstable_by(|a, b| b.bytes.cmp(&a.bytes));
        if small > 0 {
            kept.push(Entry::aggregated(small));
        }
        kept
    }
}
