//! Text rendering of the tree.

use crate::entry::Entry;
use crate::width;

pub struct Layout {
    /// Columns available for tree prefix plus name.
    pub name_col: usize,
    /// Columns of the bar graph (may be bogus on absurdly narrow terminals).
    pub bar_width: usize,
    pub ascii: bool,
    pub bytes: bool,
}

impl Layout {
    pub fn new(columns: Option<u16>, ascii: bool, bytes: bool) -> Layout {
        let cols: u16 = columns.unwrap_or(80);
        let total = cols.wrapping_sub(15) as usize + 15;
        let name_col = std::cmp::max(total / 4, 29) - 4;
        let bar_width = total.wrapping_sub(name_col).wrapping_sub(22);
        Layout {
            name_col,
            bar_width,
            ascii,
            bytes,
        }
    }
}

const KIB: u64 = 1024;
const MIB: u64 = KIB * 1024;
const GIB: u64 = MIB * 1024;
const TIB: u64 = GIB * 1024;

pub fn format_size(n: u64, raw: bool) -> String {
    if raw || n < KIB {
        format!("{} B", n)
    } else if n < MIB {
        format!("{:.2} KiB", n as f64 / KIB as f64)
    } else if n < GIB {
        format!("{:.2} MiB", n as f64 / MIB as f64)
    } else if n < TIB {
        format!("{:.2} GiB", n as f64 / GIB as f64)
    } else {
        format!("{:.2} TiB", n as f64 / TIB as f64)
    }
}

fn percent(part: u64, whole: u64) -> u64 {
    if whole == 0 {
        0
    } else {
        part.wrapping_mul(100) / whole
    }
}

/// Bar graph for an entry.  `chain` holds the reference size of the top
/// level followed by the sizes of all ancestors and of the entry itself.
fn bar(chain: &[u64], width: usize, ascii: bool) -> String {
    let mut out = String::with_capacity(width);
    let shades: [char; 5] = if ascii {
        [' ', '#', '#', '#', '#']
    } else {
        [' ', '\u{2591}', '\u{2592}', '\u{2593}', '\u{2588}']
    };
    let full = if ascii { '#' } else { '\u{2588}' };

    let levels = chain.len() - 1;
    let w = width as u64;
    let mut starts: Vec<u64> = Vec::with_capacity(levels);
    let mut len = w;
    for k in 1..chain.len() {
        len = if chain[k - 1] == 0 {
            0
        } else {
            len.wrapping_mul(chain[k]) / chain[k - 1]
        };
        starts.push((w + 1).wrapping_sub(len));
    }

    let mut level = 0usize;
    for x in 0..w {
        if level < levels && x >= starts[level] {
            level += 1;
        }
        let c = if level == levels {
            full
        } else {
            shades[std::cmp::min(level, 4)]
        };
        out.push(c);
    }
    out
}

pub fn print_tree(title: &str, total: u64, children: Option<&Vec<Entry>>, layout: &Layout) {
    println!("[ {} {} ]", title, format_size(total, layout.bytes));
    if let Some(list) = children {
        if list.is_empty() {
            return;
        }
        let top = list.iter().map(|e| e.bytes).max().unwrap_or(0);
        let mut chain = vec![top];
        let mut open = Vec::new();
        print_level(list, total, &mut chain, &mut open, layout);
    }
}

fn print_level(
    list: &[Entry],
    parent: u64,
    chain: &mut Vec<u64>,
    open: &mut Vec<bool>,
    layout: &Layout,
) {
    for (i, e) in list.iter().enumerate() {
        let last = i + 1 == list.len();
        let indent = 3 * (open.len() + 1);
        if indent > layout.name_col {
            continue;
        }

        let mut line = String::new();
        for &o in open.iter() {
            line.push_str(if o { "\u{2502}  " } else { "   " });
        }
        line.push_str(if last { "\u{2514}\u{2500} " } else { "\u{251c}\u{2500} " });

        let (text, pad) = width::fit(&e.name, layout.name_col - indent);
        match &e.color {
            Some(c) => {
                line.push_str("\x1b[");
                line.push_str(c);
                line.push('m');
                line.push_str(&text);
                line.push_str("\x1b[0m");
            }
            None => line.push_str(&text),
        }
        for _ in 0..pad {
            line.push(' ');
        }
        line.push_str(" \u{2502}");

        chain.push(e.bytes);
        line.push_str(&bar(chain, layout.bar_width, layout.ascii));
        line.push('\u{2502}');
        line.push_str(&format!(
            " {:>3}% {:>13}",
            percent(e.bytes, parent),
            format_size(e.bytes, layout.bytes)
        ));
        println!("{}", line);

        if let Some(sub) = &e.children {
            if !sub.is_empty() {
                open.push(!last);
                print_level(sub, e.bytes, chain, open, layout);
                open.pop();
            }
        }
        chain.pop();
    }
}
