//! Command line front end.

use std::path::Path;
use std::process::exit;

use crate::entry::{display_name, Entry, ScanOptions};
use crate::opts::{self, HasArg, Occur, OptSpec};
use crate::render::{self, Layout};
use crate::{colors, term};

const VERSION: &str = "0.2.18";

const OPTIONS_HELP: &str = "Options:
    -d, --depth [DEPTH] show directories up to depth N (def 1)
    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)
    -s, --summary       equivalent to -da, or -d1 -a1M
    -u, --usage         report real disk usage instead of file size
    -b, --bytes         print sizes in bytes
    -f, --files-only    skip directories for a fast local overview
    -x, --exclude NAME  exclude matching files or directories
    -H, --no-hidden     exclude hidden files
    -A, --ascii         ASCII characters only, no colors
    -h, --help          show help
    -v, --version       print version number";

fn spec(short: char, long: &'static str, hasarg: HasArg, occur: Occur) -> OptSpec {
    OptSpec {
        short,
        long,
        hasarg,
        occur,
    }
}

fn option_specs() -> Vec<OptSpec> {
    use HasArg::*;
    use Occur::*;
    vec![
        spec('d', "depth", Maybe, Optional),
        spec('a', "aggr", Maybe, Optional),
        spec('s', "summary", No, Optional),
        spec('u', "usage", No, Optional),
        spec('b', "bytes", No, Optional),
        spec('f', "files-only", No, Optional),
        spec('x', "exclude", Yes, Multi),
        spec('H', "no-hidden", No, Optional),
        spec('A', "ascii", No, Optional),
        spec('h', "help", No, Optional),
        spec('v', "version", No, Optional),
    ]
}

fn print_usage(program: &str) {
    println!(
        "Usage: {} [options] <path> [<path>..]\n\n{}",
        program, OPTIONS_HELP
    );
}

/// Name shown for a path given on the command line.  Directories are
/// shown under their canonical name so that `.` and friends make sense.
fn root_name(path: &str) -> String {
    let p = Path::new(path);
    let is_dir = std::fs::symlink_metadata(p)
        .map(|m| m.is_dir())
        .unwrap_or(false);
    if is_dir {
        if let Ok(canon) = std::fs::canonicalize(p) {
            return match canon.file_name() {
                Some(n) => display_name(n),
                None => canon.to_string_lossy().into_owned(),
            };
        }
    }
    match p.file_name() {
        Some(n) => display_name(n),
        None => path.to_string(),
    }
}

/// Parse the argument of `-a`: a decimal number with an optional unit
/// character (K, M, G or T; any other character means bytes).
fn parse_aggregate(text: &str) -> u64 {
    if !crate::size_argument_is_valid(text) {
        eprintln!("invalid argument '{}'", text);
        exit(1);
    }
    let last = text.chars().last().unwrap();
    let (number, factor): (&str, u64) = if last.is_numeric() {
        (text, 1)
    } else {
        let digits = &text[..text.len() - last.len_utf8()];
        let factor = match last {
            'k' | 'K' => 1u64 << 10,
            'm' | 'M' => 1u64 << 20,
            'g' | 'G' => 1u64 << 30,
            't' | 'T' => 1u64 << 40,
            _ => 1,
        };
        (digits, factor)
    };
    crate::parse_size_number(number).wrapping_mul(factor)
}

pub fn run() {
    term::handle_broken_pipe();

    let args: Vec<String> = std::env::args().collect();
    let program = args.first().cloned().unwrap_or_default();
    let rest: Vec<String> = if args.is_empty() {
        Vec::new()
    } else {
        args[1..].to_vec()
    };

    let specs = option_specs();
    let matches = match opts::parse(&specs, &rest) {
        Ok(m) => m,
        Err(e) => {
            print_usage(&program);
            eprintln!("{}", e);
            exit(1);
        }
    };

    if matches.present("help") {
        print_usage(&program);
        return;
    }
    if matches.present("version") {
        println!("dutree version {}", VERSION);
        return;
    }

    let ascii = matches.present("ascii");
    let ls_colors = std::env::var("LS_COLORS").unwrap_or_default();
    let dict = colors::parse(&ls_colors);

    let paths: Vec<String> = if matches.free.is_empty() {
        vec![".".to_string()]
    } else {
        matches.free.clone()
    };
    for p in &paths {
        if !Path::new(p).exists() {
            eprintln!("path {} doesn't exist", p);
            exit(1);
        }
    }

    let mut aggregate = matches.value_or("aggr", "1M").map(|s| parse_aggregate(&s));
    let mut depth = matches
        .value_or("depth", "1")
        .map(|s| s.parse::<u8>().unwrap_or(1) as usize);
    if matches.present("summary") {
        depth = Some(1);
        aggregate = Some(1 << 20);
    }

    let scan = ScanOptions {
        max_depth: depth,
        aggregate,
        usage: matches.present("usage"),
        files_only: matches.present("files-only"),
        excludes: matches.all_values("exclude"),
        no_hidden: matches.present("no-hidden"),
        colors: if ascii { None } else { Some(dict) },
    };

    let layout = Layout::new(term::stdout_columns(), ascii, matches.present("bytes"));

    if paths.len() == 1 {
        let root = Entry::scan(Path::new(&paths[0]), root_name(&paths[0]), 0, &scan);
        render::print_tree(&root.name, root.bytes, root.children.as_ref(), &layout);
    } else {
        let mut list: Vec<Entry> = paths
            .iter()
            .map(|p| Entry::scan(Path::new(p), root_name(p), 0, &scan))
            .collect();
        list.sort_unstable_by(|a, b| b.bytes.cmp(&a.bytes));
        let total = list.iter().fold(0u64, |acc, e| acc.wrapping_add(e.bytes));
        render::print_tree("<collection>", total, Some(&list), &layout);
    }
}
