        let factor = match last {
            'k' | 'K' => 1u64 << 10,
            'm' | 'M' => 1u64 << 20,
            'g' | 'G' => 1u64 << 30,
            't' | 'T' => 1u64 << 40,
            _ => 1,
        };
        (digits, factor)
    };
    crate::parse_size_number(number).wrapping_mul(factor)
}

pub fn run() {
    term::handle_broken_pipe();

    let args: Vec<String> = std::env::args().collect();
    let program = args.first().cloned().unwrap_or_default();
    let rest: Vec<String> = if args.is_empty() {
        Vec::new()
    } else {
        args[1..].to_vec()
    };

    let specs = option_specs();
    let matches = match opts::parse(&specs, &rest) {
        Ok(m) => m,
        Err(e) => {
            print_usage(&program);
            eprintln!("{}", e);
            exit(1);
        }
    };

    if matches.present("help") {
        print_usage(&program);
        return;
    }
    if matches.present("version") {
        println!("dutree version {}", VERSION);
        return;
    }

    let ascii = matches.present("ascii");
    let ls_colors = std::env::var("LS_COLORS").unwrap_or_default();
    let dict = colors::parse(&ls_colors);

    let paths: Vec<String> = if matches.free.is_empty() {
        vec![".".to_string()]
    } else {
        matches.free.clone()
    };
    for p in &paths {
        if !Path::new(p).exists() {
            eprintln!("path {} doesn't exist", p);
            exit(1);
        }
    }

    let mut aggregate = matches.value_or("aggr", "1M").map(|s| parse_aggregate(&s));
    let mut depth = matches
        .value_or("depth", "1")
        .map(|s| s.parse::<u8>().unwrap_or(1) as usize);
    if matches.present("summary") {
        depth = Some(1);
        aggregate = Some(1 << 20);
    }

    let scan = ScanOptions {
        max_depth: depth,
        aggregate,
        usage: matches.present("usage"),
        files_only: matches.present("files-only"),
        excludes: matches.all_values("exclude"),
        no_hidden: matches.present("no-hidden"),
        colors: if ascii { None } else { Some(dict) },
    };

    let layout = Layout::new(term::stdout_columns(), ascii, matches.present("bytes"));

    if paths.len() == 1 {
        let root = Entry::scan(Path::new(&paths[0]), root_name(&paths[0]), 0, &scan);
        render::print_tree(&root.name, root.bytes, root.children.as_ref(), &layout);
    } else {
        let mut list: Vec<Entry> = paths
            .iter()
            .map(|p| Entry::scan(Path::new(p), root_name(p), 0, &scan))
            .collect();
        list.sort_unstable_by(|a, b| b.bytes.cmp(&a.bytes));
        let total = list.iter().fold(0u64, |acc, e| acc.wrapping_add(e.bytes));
        render::print_tree("<collection>", total, Some(&list), &layout);
    }
}
